use std::collections::BTreeSet;

#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub struct Point64(pub i64, pub i64);

impl Point64 {
    pub const fn new(x: i64, y: i64) -> Self {
        Self(x, y)
    }
}

pub type Path64 = Vec<Point64>;
pub type Paths64 = Vec<Path64>;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum FillRule {
    EvenOdd,
    NonZero,
    Positive,
    Negative,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) struct Rect64 {
    pub left: i64,
    pub top: i64,
    pub right: i64,
    pub bottom: i64,
}

impl Rect64 {
    pub(crate) fn new(left: i64, top: i64, right: i64, bottom: i64) -> Option<Self> {
        if left < right && top < bottom {
            Some(Self {
                left,
                top,
                right,
                bottom,
            })
        } else {
            None
        }
    }

    pub(crate) fn contains_cell(&self, left: i64, top: i64, right: i64, bottom: i64) -> bool {
        self.left <= left && right <= self.right && self.top <= top && bottom <= self.bottom
    }

    pub(crate) fn as_path(self) -> Path64 {
        vec![
            Point64::new(self.left, self.top),
            Point64::new(self.right, self.top),
            Point64::new(self.right, self.bottom),
            Point64::new(self.left, self.bottom),
        ]
    }
}

pub(crate) fn paths_to_rects(paths: &Paths64) -> Vec<Rect64> {
    paths.iter().filter_map(path_to_rect).collect()
}

fn path_to_rect(path: &Path64) -> Option<Rect64> {
    if path.len() < 4 {
        return None;
    }

    let mut xs = BTreeSet::new();
    let mut ys = BTreeSet::new();

    for point in path {
        xs.insert(point.0);
        ys.insert(point.1);
    }

    if xs.len() != 2 || ys.len() != 2 {
        return None;
    }

    let mut x_values = xs.into_iter();
    let left = x_values.next()?;
    let right = x_values.next()?;

    let mut y_values = ys.into_iter();
    let top = y_values.next()?;
    let bottom = y_values.next()?;

    if !path.iter().all(|point| {
        (point.0 == left || point.0 == right) && (point.1 == top || point.1 == bottom)
    }) {
        return None;
    }

    Rect64::new(left, top, right, bottom)
}

