use std::collections::BTreeSet;

use super::geometry::{paths_to_rects, FillRule, Path64, Paths64, Rect64};

#[derive(Clone, Copy)]
enum BooleanOp {
    Intersect,
    Union,
    Difference,
    Xor,
}

#[allow(non_snake_case)]
pub fn Intersect(subjects: &Paths64, clips: &Paths64, fill_rule: FillRule) -> Paths64 {
    run_boolean_op(subjects, clips, fill_rule, BooleanOp::Intersect)
}

#[allow(non_snake_case)]
pub fn Union(subjects: &Paths64, clips: &Paths64, fill_rule: FillRule) -> Paths64 {
    run_boolean_op(subjects, clips, fill_rule, BooleanOp::Union)
}

#[allow(non_snake_case)]
pub fn Difference(subjects: &Paths64, clips: &Paths64, fill_rule: FillRule) -> Paths64 {
    run_boolean_op(subjects, clips, fill_rule, BooleanOp::Difference)
}

#[allow(non_snake_case)]
pub fn Xor(subjects: &Paths64, clips: &Paths64, fill_rule: FillRule) -> Paths64 {
    run_boolean_op(subjects, clips, fill_rule, BooleanOp::Xor)
}

fn run_boolean_op(
    subjects: &Paths64,
    clips: &Paths64,
    _fill_rule: FillRule,
    op: BooleanOp,
) -> Paths64 {
    let subject_rects = paths_to_rects(subjects);
    let clip_rects = paths_to_rects(clips);

    if subject_rects.is_empty() && clip_rects.is_empty() {
        return Vec::new();
    }

    let xs = collect_boundaries(&subject_rects, &clip_rects, |rect| [rect.left, rect.right]);
    let ys = collect_boundaries(&subject_rects, &clip_rects, |rect| [rect.top, rect.bottom]);

    if xs.len() < 2 || ys.len() < 2 {
        return Vec::new();
    }

    let mut result = Vec::new();

    for x_pair in xs.windows(2) {
        for y_pair in ys.windows(2) {
            let left = x_pair[0];
            let right = x_pair[1];
            let top = y_pair[0];
            let bottom = y_pair[1];

            let in_subject = cell_is_covered(&subject_rects, left, top, right, bottom);
            let in_clip = cell_is_covered(&clip_rects, left, top, right, bottom);

            let include = match op {
                BooleanOp::Intersect => in_subject && in_clip,
                BooleanOp::Union => in_subject || in_clip,
                BooleanOp::Difference => in_subject && !in_clip,
                BooleanOp::Xor => in_subject ^ in_clip,
            };

            if include {
                result.push(rect_to_path(left, top, right, bottom));
            }
        }
    }

    result
}

fn collect_boundaries<F>(subjects: &[Rect64], clips: &[Rect64], pick: F) -> Vec<i64>
where
    F: Fn(&Rect64) -> [i64; 2],
{
    let mut values = BTreeSet::new();

    for rect in subjects {
        values.extend(pick(rect));
    }

    for rect in clips {
        values.extend(pick(rect));
    }

    values.into_iter().collect()
}

fn cell_is_covered(rects: &[Rect64], left: i64, top: i64, right: i64, bottom: i64) -> bool {
    rects
        .iter()
        .any(|rect| rect.contains_cell(left, top, right, bottom))
}

fn rect_to_path(left: i64, top: i64, right: i64, bottom: i64) -> Path64 {
    Rect64 {
        left,
        top,
        right,
        bottom,
    }
    .as_path()
}

