fn boolean_rect_op<F>(subjects: &[Vec<super::types::Point64>], clips: &[Vec<super::types::Point64>], predicate: F) -> Paths64
where
    F: Fn(bool, bool) -> bool,
{
    let subject_rects = match collect_rects(subjects) {
        Some(rects) => rects,
        None => return Vec::new(),
    };
    let clip_rects = match collect_rects(clips) {
        Some(rects) => rects,
        None => return Vec::new(),
    };

    let mut xs = Vec::with_capacity((subject_rects.len() + clip_rects.len()) * 2);
    let mut ys = Vec::with_capacity((subject_rects.len() + clip_rects.len()) * 2);

    for rect in subject_rects.iter().chain(clip_rects.iter()) {
        xs.push(rect.left);
        xs.push(rect.right);
        ys.push(rect.top);
        ys.push(rect.bottom);
    }

    xs.sort_unstable();
    xs.dedup();
    ys.sort_unstable();
    ys.dedup();

    let mut cells = Vec::new();
    for y_pair in ys.windows(2) {
        for x_pair in xs.windows(2) {
            let cell = Rect64 {
                left: x_pair[0],
                top: y_pair[0],
                right: x_pair[1],
                bottom: y_pair[1],
